#define main legacy_main
#include "ring-cuda/main.cu"
#undef main
#include <unistd.h>
#include <dlfcn.h>
#include <cstdlib>
void checked(cudaError_t s){if(s!=cudaSuccess){fprintf(stderr,"CUDA failure: %s\n",cudaGetErrorString(s));exit(2);}}
void guard(bool initial=false){const char*visibility=getenv("CUDA_VISIBLE_DEVICES");if(!visibility||strcmp(visibility,"5,6"))exit(3);FILE*f=popen("nvidia-smi -i 5 --query-compute-apps=pid --format=csv,noheader,nounits","r");if(!f)exit(3);char line[128];while(fgets(line,sizeof(line),f)){long pid=strtol(line,nullptr,10);if(pid>0&&pid!=getpid()){fprintf(stderr,"Environment blocked: external PID%ld onGPU5\n",pid);exit(3);}}if(pclose(f)!=0)exit(3);if(initial){f=popen("nvidia-smi -i 5 --query-gpu=memory.used --format=csv,noheader,nounits","r");if(!f||!fgets(line,sizeof(line),f)||strtol(line,nullptr,10)!=0)exit(3);if(pclose(f)!=0)exit(3);}}
void sync_both(){for(int i=0;i<2;i++){checked(cudaSetDevice(i));checked(cudaDeviceSynchronize());}}
int main(){guard(true);int count;checked(cudaGetDeviceCount(&count));if(count!=2)return 3;int n=65536,repeat=10;std::vector<int>input(n),out(n),values;std::iota(input.begin(),input.end(),0);int*buffers[2];for(int i=0;i<2;i++){checked(cudaSetDevice(i));checked(cudaMalloc(&buffers[i],n*4));}
auto reset=[&](){for(int i=0;i<2;i++){checked(cudaSetDevice(i));checked(cudaMemset(buffers[i],0,n*4));}checked(cudaMemcpy(buffers[0],input.data(),n*4,cudaMemcpyDefault));sync_both();};auto exchange=[&](){for(int j=0;j<repeat;j++)for(int i=0;i<2;i++)checked(cudaMemcpy(buffers[(i+1)%2],buffers[i],n*4,cudaMemcpyDefault));sync_both();};reset();exchange();
for(int trial=1;trial<=5;trial++){guard();reset();auto start=std::chrono::steady_clock::now();exchange();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;values.clear();bool correct=true;for(int i=0;i<2;i++){checked(cudaSetDevice(i));checked(cudaMemcpy(out.data(),buffers[i],n*4,cudaMemcpyDefault));correct &=out==input;values.insert(values.end(),out.begin(),out.end());}guard();char path[32];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(values.data(),4,values.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.14g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"timing_region\":\"mean_two_device_ring_round_with_final_both_device_fences\",\"jit_excluded\":true,\"internal_repeats\":%d,\"devices_checked\":2,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",values.size(),correct?0:1,repeat,path,values.size());if(!correct)return 1;}int version;checked(cudaRuntimeGetVersion(&version));Dl_info info;dladdr((void*)cudaMemcpy,&info);printf("STUDY_CUDART %s version=%d\n",info.dli_fname,version);for(int i=0;i<2;i++){checked(cudaSetDevice(i));checked(cudaFree(buffers[i]));}}
